def removeStones(stones):
    parent = {}

    def find(x):
        if x not in parent:
            parent[x] = x
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for x, y in stones:
        a, b = find(x), find(~y)
        if a != b:
            parent[a] = b
    groups = {find(x) for x, y in stones}
    return len(stones) - len(groups)
